import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { analyzeSource, fileSourceAsIs } from "@/lib/ingest";
import { resolveIngestModel, recommendIngestModel } from "@/lib/models";
import { isTranscribedExtractor } from "@/lib/stt";
import { checkDailyBudget, budgetExceededMessage } from "@/lib/cost";
import { beginInflight, endInflight } from "@/lib/inflight";

// 스테이징된 자료를 ★실행★ — mode:"llm"=LLM 분석(토큰), mode:"raw"=원본 그대로 파일링(토큰 0).
export const runtime = "nodejs";
export const maxDuration = 600; // 무거운 자료를 추론 모델(claude/codex)이 분석할 때 길어질 수 있음(타임아웃 600초와 정렬)

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source) return NextResponse.json({ error: "자료를 찾을 수 없습니다." }, { status: 404 });
  // ACL: 접근 가능한 scope의 자료만(인제스트 적용 강제지점).
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(source.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });

  const { mode, model, reanalyze, diarize, meeting } = await req.json().catch(() => ({}));
  try {
    if (mode === "raw") {
      // 토큰 0 — 이미 정리된 텍스트를 위키 페이지로 직접 파일링.
      return NextResponse.json(await fileSourceAsIs(id));
    }
    // mode "llm"(기본): 비용 상한 체크 후 실제 LLM 인제스트.
    const budget = await checkDailyBudget(user.id, source.teamScope);
    if (budget.exceeded) {
      return NextResponse.json({ error: budgetExceededMessage(budget) }, { status: 429 });
    }
    // ★다시 분석★: 이미 분석된 자료를 재분석할 때, 기존 잡을 지워 ingestText의 dedup(SKIPPED_DUP)을 우회해
    //   실제 재인제스트가 돌게 한다. (증강 재실행은 원본의 '관련 분석' 섹션을 멱등하게 갱신.)
    if (reanalyze) await prisma.ingestJob.deleteMany({ where: { sourceId: id } });
    // 모델 선택: 사용자가 셀렉트박스에서 ★직접 고른 경우만★ 그 모델을 쓰고, 아니면(자동) ★자료 형식 기반 추천★.
    //   → 신규 업로드뿐 아니라 ★재처리·원본추가★도 자료(확장자)에 맞는 최적 모델로 자동 분석된다(PDF·표·텍스트별).
    let picked: { model: string; provider: string; think: boolean };
    if (typeof model === "string" && model) {
      picked = await resolveIngestModel(model);
    } else {
      // ★전사 소스(extractor groq-/gemini-)는 byteSize가 '오디오 바이트'라 텍스트 길이가 아님 → 크기 휴리스틱 제외★
      //   (안 그러면 모든 음성이 '큰 자료'로 오인돼 유료 추론 모델로 자동 라우팅됨). 표시 추천과도 일치.
      const transcribed = isTranscribedExtractor(source.extractor);
      const reco = await recommendIngestModel({ type: source.type, chars: transcribed ? undefined : (source.byteSize ?? undefined), transcribed });
      picked = { model: reco.model, provider: reco.provider, think: false };
    }
    // ★원본 보존 + 그래프 증강★: 원본이 이미 topic으로 보존돼 있으면 analyzeSource가 증강 모드로 처리(원본 유지,
    //   entities/concepts만 추가, 원본엔 링크만 덧붙임).
    // 취소: req.signal(클라 abort) + 서버측 in-flight 컨트롤러를 함께 사용한다. nginx 뒤에서 req.signal이
    //   발화하지 않아도, /cancel 엔드포인트가 이 컨트롤러를 직접 abort해 LLM 서브프로세스까지 중단을 전파한다.
    const inflight = beginInflight("analyze", id, user.id, source.teamScope, req.signal);
    try {
      const result = await analyzeSource(id, { model: picked.model, provider: picked.provider, think: picked.think, signal: inflight.signal, diarize: !!diarize, meeting: !!meeting });
      return NextResponse.json(result);
    } finally {
      endInflight("analyze", id, inflight);
    }
  } catch (err) {
    return NextResponse.json({ error: String(err) }, { status: 500 });
  }
}

import { createHash } from "node:crypto";
import { promises as fs } from "node:fs";
import path from "node:path";
import { prisma } from "./db";
import { createNotification } from "./notifications";
import { callStructured, MODELS, providerFor, promptTier, type BuiltPrompt } from "./anthropic";
import { claudeCliPromptHint } from "./claude-cli";
import { codexPromptHint } from "./codex";
import { openaiPromptHint } from "./openai";
import { loadSecrets } from "./secrets";
import { fallbackChainFor } from "./fallback";
import { disabledModelIds } from "./modelSettings";
import { wikiAbsPath } from "./wiki/paths";
import { resolveQueryScopes } from "./acl/scope";
import { assertWikiReady, commitAll, withWikiWriteLock } from "./wiki/repo";
import { applyEditSet, coercePath, type EditSet } from "./wiki/applyEditSet";
import { atomicWriteFile } from "./wiki/atomicWrite";
import { kstStamp } from "./time";
import { loadBrain, loadIndex, loadPages, type WikiPage } from "./wiki/context";
import { rankPages, warmPageEmbeddings } from "./wiki/rank";
import { syncWikiDocs } from "./wiki/searchIndex";
import { regenerateIndex } from "./wiki/maintenance";
import { embedOne } from "./embed";
import { recordUsage } from "./cost";
import { getIngestReviewThreshold } from "./settings";
import { sniffImageMime, extractAsset } from "./extract";
import { transcribe, isTranscribedExtractor } from "./stt";
import { meetingPromptGuidance } from "./meeting";
import { isBlockingDup } from "./dedup";

// PDF·문서를 ★원본 그대로(네이티브)★ 모델에 첨부할 수 있는 공급자 — 표·레이아웃을 모델이 직접 읽는다.
//   anthropic·gemini만 지원(ollama는 무시, openai-compat/Groq는 문서 전송 미구현).
function supportsNativeDocs(provider: string): boolean {
  return provider === "anthropic" || provider === "gemini";
}

// 인제스트 편집셋 ★출력 토큰 상한★ — 잘림(MAX_TOKENS로 편집셋 truncate)을 줄이려 ★공급자 최대 출력★을 기본으로.
//   env INGEST_MAX_TOKENS로 조정 가능하나, 공급자 최대를 넘기면 API 400 → cap으로 클램프한다.
//   gemini-2.5-flash=65536(최대), 그 외(claude/groq 등)는 안전하게 기존 32768 유지.
function ingestMaxTokens(provider?: string): number {
  const cap = provider === "gemini" ? 65536 : provider === "openai" ? 16384 : 32768; // OpenAI 챗 모델 출력 상한(gpt-4o류 16384)에 안전하게 맞춤(초과 시 400)
  const env = Number(process.env.INGEST_MAX_TOKENS || 0);
  return env > 0 ? Math.min(env, cap) : cap;
}

export interface IngestInput {
  scope?: string; // 위키 디렉터리 경로(common/personal/<id>/project-<slug>)
  title: string;
  text: string; // md 본문(텍스트) 또는 이미지 캡션/지시
  type?: string; // 기본 'MD' (이미지는 'IMAGE')
  userId?: number | null; // 업로더(provenance) — ★감사용으로 항상 기록★(anonymous여도)
  anonymous?: boolean; // true=동료 화면에 업로더를 '익명 기여자'로 표시(uploadedBy는 유지)
  images?: { mediaType: string; dataBase64: string }[]; // 멀티모달: 첨부 이미지(비전)
  documents?: { mediaType: string; dataBase64: string }[]; // 첨부 문서(PDF)
  signal?: AbortSignal; // 분석 취소 — abort 시 LLM 호출/CLI 서브프로세스를 중단(위키 쓰기 전에 throw)
  rawBytes?: Buffer; // 원본 스냅샷을 바이트로 저장(이미지·PDF 등). 없으면 text 저장
  rawExt?: string; // 원본 확장자(기본 'md')
  // 4h 추출 메타·자산 (docs/17)
  mimeType?: string;
  byteSize?: number;
  originalName?: string;
  extractor?: string;
  extractStatus?: string; // FULL|PARTIAL|NONE|UNANALYZED
  normalizedText?: string; // 추출 정규화본(텍스트경로) → <sha>.normalized.md 사이드카
  assets?: { name: string; bytes: Buffer; mediaType: string }[]; // 문서 내장 이미지(raw 보존 + 비전 첨부)
  model?: string; // 사용자가 자료 탭에서 선택한 인제스트 모델(미지정 시 환경 기본)
  provider?: string; // 위 모델의 공급자(미지정 시 환경 기본)
  think?: boolean; // 로컬 추론모델 thinking 모드(빠름/추론 선택)
  // ★증강 모드★ — 원본이 이미 위키 topic(preservePath)으로 보존돼 있을 때(원본 그대로 추가 후 분석).
  //   원본을 요약·대체하지 않고 entities/concepts 그래프만 추가 + 원본엔 '관련 분석' 링크만 덧붙인다.
  augment?: boolean;
  preservePath?: string; // 보존할 원본 topic 경로(scope 포함) — augment 시 덮어쓰기 금지
  meeting?: boolean; // ★회의 모드(B-1)★ — 전사문일 때 회의 구조(요약·결정·액션)로 정리. strong tier에만 적용.
}

export interface IngestResult {
  status: "APPLIED" | "SKIPPED_DUP" | "NEEDS_REVIEW";
  sourceId: number;
  jobId?: number;
  commitSha?: string;
  changedPaths?: string[];
  confidence?: number;
  needsHuman?: boolean;
  usedModel?: string; // 실제 분석에 쓰인 모델(폴백 시 백업 모델)
  fallback?: { fromModel: string; reason: string }; // 1순위 대체 시 사유
}

// submit_edit_set 도구의 입력 스키마 (docs/06 §2). Phase 1은 op를 create|append로 제한.
const EDIT_SET_SCHEMA: Record<string, unknown> = {
  type: "object",
  properties: {
    edits: {
      type: "array",
      description: "위키에 적용할 파일 편집 목록",
      items: {
        type: "object",
        properties: {
          op: { type: "string", enum: ["create", "append"] },
          path: {
            type: "string",
            description:
              "scope 포함 상대경로. 예: <scope>/entities/결제-게이트웨이.md (kebab-case 파일명, scope는 시스템 지시를 따른다)",
          },
          content: {
            type: "string",
            description: "frontmatter + 본문 + 출처 섹션을 포함한 페이지 전체 markdown",
          },
        },
        required: ["op", "path", "content"],
      },
    },
    log_entry: { type: "string", description: "이 인제스트의 한 줄 이력 요약" },
    confidence: {
      type: "number",
      description: "0~1 자기평가. 새 페이지·모순은 낮게, 링크·오타정정은 높게.",
    },
    needs_human: {
      type: "boolean",
      description: "모순/대체(contradicts/supersedes) 등 사람 검토가 필요하면 true",
    },
  },
  required: ["edits", "log_entry", "confidence"],
};

function buildSystem(brain: string, scope: string, provider?: string, model?: string, hasParent?: boolean, meeting?: boolean): string {
  return [
    brain,
    "",
    "---",
    "당신은 위 '위키 두뇌' 규칙을 따르는 지식 관리자입니다. 업로드된 원본 1건을 읽고,",
    "위키에 적용할 편집셋을 submit_edit_set 도구로 제출하세요. 자유서술이 아니라 도구 호출로만 답합니다.",
    "",
    `★ 모든 편집 경로(path)는 반드시 이 scope 디렉터리 \`${scope}/\` 아래여야 합니다. 다른 scope를 건드리면 거부됩니다.`,
    "",
    "편집 규칙:",
    "- ★언어: 페이지 title(frontmatter)·본문·[[링크]]는 반드시 ★한국어★로 작성한다(원문이 외국어면 한국어로 요약·번역). 사용자 대부분이 한국어 사용자다.",
    "  단 ★파일명(path)만 로마자 kebab-case★(예: 경로 `entities/park-minsu.md`, title은 `박민수`). 제품·고유명사는 통용 표기를 쓴다.",
    `- 1 페이지 = 1 개념/개체. 파일명은 kebab-case, scope 하위 디렉터리에 둔다:`,
    `  \`${scope}/entities/\`(사람·조직·시스템·개체) · \`${scope}/concepts/\`(개념·용어) · \`${scope}/topics/\`(주제·종합).`,
    "- 각 페이지는 frontmatter(title, type, scope, links, sources, updated) + 본문 + '## 출처' 섹션.",
    "- 본문에서 다른 페이지를 언급하면 [[제목]] 형태로 상호링크한다.",
    "- 추측 금지: 원본에 없는 사실을 만들지 않는다. 모든 주장은 sources(sha256)로 뒷받침한다.",
