// 증강 시 원본 topic 끝에 붙일 '관련 분석' 링크 섹션을 ★코드가★ 생성.
// ★이 원본 sha를 인용하는 entities/concepts 페이지 전체★에서 제목을 뽑는다(이번 편집뿐 아니라 누적분 포함)
// → 재분석 때 LLM이 일부만 다시 내도 섹션은 항상 완전·정확. (pages = loadPages 결과, sha = 원본 64-hex)
function buildRelatedSection(pages: { path: string; content: string }[], sha: string): string {
  const ents: string[] = [];
  const cons: string[] = [];
  for (const pg of pages) {
    if (!pg.content.includes(sha)) continue; // 이 원본을 출처로 가진 페이지만
    const m = pg.content.match(/^title:\s*(.+)$/m);
    const title = m ? m[1].trim().replace(/^["']|["']$/g, "") : (pg.path.split("/").pop() || "").replace(/\.md$/i, "");
    if (/\/entities\//.test(pg.path)) ents.push(title);
    else if (/\/concepts\//.test(pg.path)) cons.push(title);
  }
  const uniq = (a: string[]) => [...new Set(a.filter(Boolean))].sort((x, y) => x.localeCompare(y));
  const E = uniq(ents);
  const C = uniq(cons);
  if (!E.length && !C.length) return "";
  const lines = ["## 관련 분석", "", "이 자료에서 AI가 추출·연결한 항목입니다."];
  if (E.length) lines.push("", "### 개체", ...E.map((t) => `- [[${t}]]`));
  if (C.length) lines.push("", "### 개념", ...C.map((t) => `- [[${t}]]`));
  return lines.join("\n");
}

function buildUser(args: {
  scope: string;
  title: string;
  sha: string;
  text: string;
  index: string;
  pages: { path: string; content: string }[];
  parentPages?: { path: string; content: string }[]; // 상위 룸·공통 페이지(읽기 전용 참조 — 중복생성 방지·상호링크)
  nativeAttachment?: boolean; // 이미지/PDF가 본 원본(텍스트는 캡션) — 첨부를 근거로 정리
  embeddedCount?: number; // 추출 텍스트 + 문서 내장 이미지 N장(보조)
}): string {
  const existing =
    args.pages.length === 0
      ? "(아직 위키 페이지가 없습니다 — 첫 인제스트)"
      : args.pages
          .map((p) => `### 기존페이지: ${p.path}\n${p.content}`)
          .join("\n\n");

  // 상위 룸·회사 공통 지식(읽기 전용) — 이미 있으면 다시 만들지 말고 ★전체 경로★로 상호링크하라는 참조 블록.
  const parent =
    !args.parentPages || args.parentPages.length === 0
      ? ""
      : [
          `## 상위 룸·회사 공통 지식 (★읽기 전용 · 참조용★ — 이 scope가 아니므로 생성·편집 금지)`,
          `이미 존재하는 지식이다. 같은 개체·개념을 ★다시 만들지 말고★, 본문에서 언급하면 그 페이지로 ★전체 경로 링크★ \`[제목](경로)\` 해 연결한다(이 scope 밖이라 [[제목]] 아님).`,
          ...args.parentPages.map((p) => `### 상위지식: ${p.path}\n${p.content}`),
          ``,
        ].join("\n");

  return [
    `# 인제스트 대상`,
    `scope: ${args.scope}`,
    `원본 제목: ${args.title}`,
    `원본 sha256: ${args.sha}  (frontmatter sources에 "sha256:${args.sha}" 형태로 표기)`,
    ``,
    `## 현재 목차 (${args.scope}/index.md)`,
    args.index || "(비어 있음)",
    ``,
    `## 현재 위키 페이지들 (★같은 개체·개념을 더 상세히 다루면 새로 만들지 말고 해당 path를 갱신·보강하라★)`,
    existing,
    ``,
    parent,
    args.nativeAttachment
      ? `## 원본 (첨부 자료=이미지/PDF — 첨부 내용을 근거로 정리. 아래는 캡션/지시)`
      : `## 원본 본문 (이 내용만을 근거로 정리)${args.embeddedCount ? ` — 문서 내장 이미지 ${args.embeddedCount}장 첨부(차트·표·도해 내용은 반영, 장식·로고·아이콘은 무시)` : ""}`,
    "```md",
    args.text,
    "```",
  ].join("\n");
}

// ── 인제스트 기존-위키 컨텍스트 트림(품질 중립) ──────────────────────────────
// strong 공급자 인제스트는 모순·중복 검사용으로 기존 위키 페이지를 프롬프트에 싣는다. 위키가 커지면
//   매 인제스트 입력 토큰이 무한정 늘어난다 → 새 자료와 ★관련된 페이지만★ 의미검색 상위 N개로 추린다.
//   ★상한 이하면 손대지 않음(작은 위키 회귀 0). 유지 페이지는 본문 절단 없음(꼬리에 숨은 모순 보존).★
//   임베딩(ollama) 다운 시 rankPages가 키워드 폴백. INGEST_EXISTING_MAX_PAGES=0/음수면 상한 해제(현행 전체 전송).
const INGEST_EXISTING_CAP = Number(process.env.INGEST_EXISTING_MAX_PAGES || 20);
async function trimExistingPages(scope: string, pages: WikiPage[], title: string, text: string): Promise<WikiPage[]> {
  if (INGEST_EXISTING_CAP <= 0 || pages.length <= INGEST_EXISTING_CAP) return pages; // 작은 위키·해제 시 현행 그대로
  const probe = `${title}\n${text.slice(0, 4000)}`; // 새 자료를 질의 벡터로 → 관련 기존 페이지 상위 N개
  const qVec = await embedOne(probe);
  const ranked = await rankPages(scope, pages, probe, qVec);
  return ranked.slice(0, INGEST_EXISTING_CAP); // 본문 절단 없음 — 무관 페이지 통째 드롭으로만 절감
}

// ── 상위 룸·회사 공통 읽기전용 참조 (서브룸 상호링크·중복생성 방지) ──────────────────
// 서브룸 인제스트 시 조상 체인(resolveQueryScopes = 부모·조부모 …, +inheritsCommon이면 공통) 페이지를
//   ★읽기 전용 참조★로 프롬프트에 싣는다 → LLM이 상위에 이미 있는 개체를 이 scope에 다시 만들지 않고
//   전체 경로로 상호링크한다(읽기 측은 이미 교차-scope 인용을 열어줌). ★쓰기는 여전히 자기 scope만★(단일 라이터 유지).
//   비용은 새 자료와 관련도 상위 N개로 컷(작으면 전체). INGEST_PARENT_MAX_PAGES=0이면 비활성.
const INGEST_PARENT_CAP = Number(process.env.INGEST_PARENT_MAX_PAGES || 8);
async function loadAncestorPages(scope: string, title: string, text: string): Promise<WikiPage[]> {
  if (INGEST_PARENT_CAP <= 0) return [];
  const chain = await resolveQueryScopes(scope); // [자기, 부모, 조부모, …(+공통)]
  const ancestors = chain.filter((s) => s !== scope); // 자기 제외 = 상속받는 상위·공통만
  if (!ancestors.length) return []; // 최상위 룸·common·personal = 부모 없음
  const all: WikiPage[] = [];
  for (const anc of ancestors) all.push(...(await loadPages(anc)));
  if (all.length <= INGEST_PARENT_CAP) return all;
  // 새 자료와 관련된 상위 페이지만 — 의미검색(임베딩 다운 시 rankPages가 키워드 폴백).
  const probe = `${title}\n${text.slice(0, 4000)}`;
  const qVec = await embedOne(probe);
  const ranked = await rankPages(scope, all, probe, qVec);
  return ranked.slice(0, INGEST_PARENT_CAP);
}

// ── 갱신 시 원본(sha) 출처 보존·누적 (결정적 보장) ──────────────────────────────
// 위키 페이지를 갱신(op:create 재작성·덮어쓰기)할 때 LLM이 기존 '## 출처'의 sha를 빠뜨리면
//   '원본 자료' 박스(app/api/wiki = 본문 sha 스캔 + Source.id순)에서 원본 출처가 사라진다.
//   → 적용 후 코드가 ★누락 sha를 '## 출처'에 보강★해 원본+신규가 모두 남게 한다(buildRelatedSection과 동일 철학).
//   박스 순서는 Source.id(업로드 순)라 파일 내 위치는 무관 — '존재'만 보장하면 된다.
function extractShas(content: string): string[] {
  return [...new Set([...content.matchAll(/sha256:([a-f0-9]{64})/g)].map((m) => m[1]))];
}

// 페이지의 '## 출처' 섹션에 누락된 sha만 보강(멱등). 수정했으면 true.
async function ensureSourcesSection(abs: string, requiredShas: string[]): Promise<boolean> {
  let content: string;
  try { content = await fs.readFile(abs, "utf8"); } catch { return false; } // 파일 없으면 건너뜀
  const present = new Set(extractShas(content));
  const missing = requiredShas.filter((s) => s && !present.has(s));
  if (!missing.length) return false;
  const add = missing.map((s) => `- sha256:${s}`).join("\n");
  if (/(^|\n)##\s*출처[^\n]*\n/.test(content)) {
    content = content.replace(/((^|\n)##\s*출처[^\n]*\n)/, `$1${add}\n`); // 기존 헤더 바로 뒤에 끼움
  } else {
    content = content.replace(/\s*$/, "") + `\n\n## 출처\n${add}\n`; // 섹션 없으면 파일 끝에 생성
  }
  await atomicWriteFile(abs, content); // 원자적(읽기 파드 보호)
  return true;
}

// ── 로컬(약한 모델)용 단순 인제스트 (PLAN-local-llm-operation §2: task 축소) ──
// 모델은 '콘텐츠만'(제목·요약·태그·본문) 내고, 경로·구조·frontmatter는 코드가 결정한다.
// → 약한 모델의 경로 오생성(`/1`) 제거 + 출력이 작아 빠름. 상호링크·index·needs_human·비전 비활성.
interface SimpleNote { title: string; tags?: string[]; body_markdown: string }

// 필드 최소화(소형 모델의 필드 드리프트 방지) — 제목·태그·본문만. 요약은 본문이 겸한다.
const SIMPLE_SCHEMA: Record<string, unknown> = {
  type: "object",
  properties: {
    title: { type: "string", description: "자료의 핵심 제목(짧게, 한국어)" },
    tags: { type: "array", items: { type: "string" }, description: "키워드 태그 3~6개" },
    body_markdown: { type: "string", description: "원문 핵심을 한국어로 정리한 markdown 본문(소제목·목록 사용 가능)" },
  },
  required: ["title", "body_markdown"],
};

const SIMPLE_SYSTEM =
  "당신은 사내 지식 정리 도우미입니다. 주어진 자료를 읽고 핵심을 한국어로 정리해 JSON으로만 답하세요. " +
  "원문에 있는 내용만 쓰고, 추측하거나 지어내지 마세요.";

function simpleUserText(title: string, text: string): string {
  return ["다음 자료를 읽고 title·tags·body_markdown 을 JSON으로 작성하세요.", "",
    "# 원본 제목", title || "(제목 없음)", "", "# 원본 내용", text].join("\n");
}

function slugify(s: string): string {
  return (s || "").trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "note";
}

// 단순 노트 → 코드가 경로·frontmatter를 정한 EditSet(1페이지). 이후 기존 적용·커밋 파이프라인 공용.
function buildSimpleEditSet(scope: string, note: SimpleNote, sha: string): EditSet {
  const title = (note.title || "제목 없는 노트").replace(/\s+/g, " ").trim();
  const slug = slugify(title);
  const tags = (note.tags ?? []).filter((t) => typeof t === "string" && t.trim()).slice(0, 8);
  const fm = ["---", `title: ${title}`, "type: note", `scope: ${scope}`,
    `tags: ${JSON.stringify(tags)}`, `sources: ${JSON.stringify([`sha256:${sha}`])}`,
    `updated: ${kstStamp()}`, "---"].join("\n");
  const content = `${fm}\n\n# ${title}\n\n` +
    `${(note.body_markdown || "").trim()}\n\n## 출처\n- sha256:${sha}\n`;
  return { edits: [{ op: "create", path: `${scope}/topics/${slug}.md`, content }], log_entry: `로컬 인제스트: ${title}`, confidence: 1, needs_human: false };
}

/**
 * 단일 원본 텍스트를 인제스트한다(정규화→sha→dedup→raw 스냅샷→편집셋→적용→커밋).
 * 공급자가 ollama면 단순 경로(콘텐츠만, 코드가 구조 결정), anthropic이면 복잡 편집셋 경로.
 * MVP는 워커를 웹 요청 안에서 인라인 동기로 실행한다(docs/08 Phase 1). Phase 3에서 별도 프로세스로 분리.
 */
export async function ingestText(input: IngestInput): Promise<IngestResult> {
  await assertWikiReady();
  const scope = input.scope ?? "common";
  const type = input.type ?? "MD";
  const text = input.text;
  const sha = createHash("sha256").update(input.rawBytes ?? Buffer.from(text, "utf8")).digest("hex");
  // 인제스트 모델/공급자/추론모드: 사용자가 자료 탭에서 고른 값(있으면) 우선, 없으면 환경 기본.
  const ingestProvider = input.provider ?? providerFor("ingest");
  const ingestModel = input.model ?? MODELS.ingest;
  const ingestThink = input.think ?? false;

  // dedup: 같은 scope에 동일 원본이 ★실제로 LLM 분석되어 적용(APPLIED)★된 적 있으면 건너뛴다.
  //   ★단 '원본 그대로'(gate=RAW_IMPORT)만 적용된 자료는 아직 ‘분석’ 전이다★ → [AI로 분석] 재인제스트를 허용해야
  //   한다(RAW_IMPORT를 '분석됨'으로 치면 SKIPPED_DUP로 빠져 LLM 호출이 통째로 건너뛰어진다). 실패/미완료도 정리 후 재시도.
  const dup = await prisma.source.findUnique({
    where: { teamScope_sha256: { teamScope: scope, sha256: sha } },
    include: { ingestJobs: { where: { status: "APPLIED", NOT: { gate: "RAW_IMPORT" } }, take: 1 } },
  });
  if (dup) {
    if (isBlockingDup({ archivedAt: dup.archivedAt, appliedJobCount: dup.ingestJobs.length })) return { status: "SKIPPED_DUP", sourceId: dup.id };
    await prisma.ingestJob.deleteMany({ where: { sourceId: dup.id } });
    await prisma.source.delete({ where: { id: dup.id } });
  }

  const now = new Date();
  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const rawExt = input.rawExt ?? "md";
  const rawRel = `raw/${scope}/${yyyy}/${mm}/${sha}.${rawExt}`;
  const stem = rawRel.replace(/\.[^.]+$/, "");
  const normalizedRel = input.normalizedText && input.normalizedText.trim() ? `${stem}.normalized.md` : null;

  const source = await prisma.source.create({
    data: {
      teamScope: scope,
      type,
      sha256: sha,
      title: input.title,
      rawPath: rawRel,
      uploadedBy: input.userId ?? null,
      anonymous: input.anonymous ?? false,
      mimeType: input.mimeType ?? null,
      byteSize: input.byteSize ?? input.rawBytes?.byteLength ?? Buffer.byteLength(text, "utf8"),
      originalName: input.originalName ?? null,
      extractor: input.extractor ?? null,
      extractStatus: input.extractStatus ?? null,
      normalizedPath: normalizedRel,
      provenance: JSON.stringify({ uploadedAt: now.toISOString() }),
    },
  });
  const job = await prisma.ingestJob.create({
    data: { sourceId: source.id, teamScope: scope, status: "RUNNING", model: ingestModel },
  });

  try {
    // 자동 폴백: 1순위 모델 한도/오류 시 백업으로(관리자가 끈 모델 제외). 실제 쓰인 모델·사유 추적.
    await loadSecrets(); // 관리자 입력 키(DB) 반영(폴백 체인·회전)
    const disabledModels = await disabledModelIds();
    const fallbacks = fallbackChainFor(ingestModel, ingestProvider).filter((f) => !disabledModels.has(f.model));

    // 강한 공급자(anthropic·gemini)면 HEAVY 컨텍스트(두뇌·목차·페이지)를 사전 로드.
    // ★폴백으로 약한 모델로 떨어지면 build가 SIMPLE로 강등★(docs/PLAN-model-prompt-strategy §3·4).
    const primaryTier = promptTier(ingestProvider);
    const heavyCtx = primaryTier === "strong"
      ? await (async () => {
          const [brain, index, pages] = await Promise.all([loadBrain(), loadIndex(scope), loadPages(scope)]);
          // 새 자료와 관련된 기존 페이지만 추려 불필요한 입력 토큰을 줄인다(작은 위키는 그대로).
          const relevant = await trimExistingPages(scope, pages, input.title, text);
          // ★상위 룸·회사 공통 읽기전용 참조★ — 서브룸이면 조상 체인 페이지를 관련도 상위 N개만 주입(중복생성 방지·상호링크).
          const parentPages = await loadAncestorPages(scope, input.title, text);
          return { brain, index, pages: relevant, parentPages };
        })()
      : null;
    const assetImages = (input.assets ?? []).map((a) => ({ mediaType: a.mediaType, dataBase64: a.bytes.toString("base64") }));
    const allImages = [...(input.images ?? []), ...assetImages];
    const nativeAttachment = ((input.images?.length ?? 0) + (input.documents?.length ?? 0) > 0) && !input.normalizedText;

    // 서빙 모델 tier별 프롬프트: strong=HEAVY 편집셋(상호링크·index 유지), weak=SIMPLE(콘텐츠만·코드가 경로).
    const build = (ctx: { tier: "strong" | "weak"; provider?: string }): BuiltPrompt => {
      if (ctx.tier === "strong" && heavyCtx) {
        const hasParent = heavyCtx.parentPages.length > 0;
        return {
          // 증강 모드(원본이 이미 topic으로 보존됨)면 ★원본 보존+그래프 추가★ 프롬프트, 아니면 일반 정리 프롬프트.
          system: input.augment && input.preservePath
            ? buildAugmentSystem(heavyCtx.brain, scope, input.preservePath, ctx.provider, ingestModel, hasParent)
            : buildSystem(heavyCtx.brain, scope, ctx.provider, ingestModel, hasParent, input.meeting),
          userText: buildUser({ scope, title: input.title, sha, text, index: heavyCtx.index, pages: heavyCtx.pages, parentPages: heavyCtx.parentPages, nativeAttachment, embeddedCount: input.assets?.length ?? 0 }),
          toolName: "submit_edit_set",
          toolDescription: "위키에 적용할 편집셋(JSON). 워커가 파일에 적용하고 git 커밋한다.",
          schema: EDIT_SET_SCHEMA,
          // strong(Gemini/Claude)은 출력 여유가 커 큰 .md 편집셋도 한 번에(잘림 방지). 공급자 최대 출력 사용(Gemini=65K).
          maxTokens: ingestMaxTokens(ctx.provider),
        };
      }
      return {
        system: SIMPLE_SYSTEM,
        userText: simpleUserText(input.title, text),
        toolName: "submit_note",
        toolDescription: "정리한 노트(JSON).",
        schema: SIMPLE_SCHEMA,
        maxTokens: Number(process.env.INGEST_MAX_TOKENS || 4096),
      };
    };

    const r = await callStructured<EditSet | SimpleNote>({
      model: ingestModel,
      provider: ingestProvider,
      think: ingestThink,
      images: allImages.length ? allImages : undefined,
      documents: input.documents,
      fallbacks,
      build,
      signal: input.signal,
    });
    const usage = r.usage;
    const servedModel = r.model;
    const fallbackInfo = r.fallback;
    // 서빙 모델 tier로 결과 해석(폴백으로 강등됐을 수 있음).
    let data: EditSet;
    if (r.tier === "strong") {
      data = r.data as EditSet;
      if (!Array.isArray(data.edits)) throw new Error("LLM이 유효한 편집셋(edits 배열)을 반환하지 않았습니다.");
    } else {
      data = buildSimpleEditSet(scope, r.data as SimpleNote, sha);
    }

    // 증강 모드: 원본 topic은 ★LLM이 손대지 않게 모든 편집 제거★(create든 append든). '관련 분석' 링크 섹션은
    //   아래에서 ★코드가 결정적으로★ 갱신한다(LLM이 append를 빼먹거나 create로 덮는 변덕에 영향 안 받음).
    if (input.augment && input.preservePath && Array.isArray(data.edits)) {
      const prot = input.preservePath;
      const norm = (p: string) => {
        let s = String(p ?? "").trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
        if (s !== scope && !s.startsWith(scope + "/")) s = `${scope}/${s}`;
        return s;
      };
      data = { ...data, edits: data.edits.filter((e) => norm(e.path) !== prot) };
    }

    // 적용 + 커밋은 단일 라이터 임계구역에서(raw 스냅샷 기록 포함).
    // 거버넌스 게이트(REQ-WIKI-007/REQ-REVIEW-004, docs/12): 모순/대체(needs_human) 또는
    // 저신뢰(confidence < 임계)면 편집셋 미적용·검토 큐로. 원본은 보존, 승인 시 적용.
    //   임계는 ★관리자 UI 설정 우선★(없으면 env INGEST_T_REVIEW·기본 0.5).
    const T_REVIEW = await getIngestReviewThreshold();
    const apply = !data.needs_human && (data.confidence ?? 1) >= T_REVIEW;
    const { commitSha, changed } = await withWikiWriteLock(async () => {
      const rawAbs = wikiAbsPath(rawRel);
      await fs.mkdir(path.dirname(rawAbs), { recursive: true });
      await fs.writeFile(rawAbs, input.rawBytes ?? text);

      const extra: string[] = [];
      // 문서 내장 이미지 자산 보존 (raw/<sha>.assets/NN.ext)
      if (input.assets?.length) {
        const assetsDir = wikiAbsPath(`${stem}.assets`);
        await fs.mkdir(assetsDir, { recursive: true });
        for (let i = 0; i < input.assets.length; i++) {
          const a = input.assets[i];
          const aext = a.mediaType.split("/")[1] || "png";
          const arel = `${stem}.assets/${String(i + 1).padStart(2, "0")}.${aext}`;
          await fs.writeFile(wikiAbsPath(arel), a.bytes);
          extra.push(arel);
        }
      }
      // 정규화 추출본 사이드카 (<sha>.normalized.md)
      if (normalizedRel) {
        await fs.writeFile(wikiAbsPath(normalizedRel), input.normalizedText!, "utf8");
        extra.push(normalizedRel);
      }

      // 갱신 전, 각 대상 페이지의 기존 sha 수집(적용 후 op:create가 옛 sha를 덮어써도 보강하기 위함).
      const preShaByPath = new Map<string, string[]>();
      if (apply) {
        for (const e of data.edits ?? []) {
          const rel = coercePath(scope, e.path);
          if (preShaByPath.has(rel)) continue;
          try { preShaByPath.set(rel, extractShas(await fs.readFile(wikiAbsPath(rel), "utf8"))); } catch { /* 새 페이지 */ }
        }
      }

      const changed = apply ? await applyEditSet(scope, data) : [];

      // ★원본 출처 보존·누적★: 변경된 지식 페이지마다 (기존 sha ∪ 이번 sha)가 본문에 모두 남도록 '## 출처' 보강.
      //   → '원본 자료' 박스에 원본+갱신 자료가 순서대로(Source.id순) 연달아 표시된다(멱등·위치 무관).
      if (apply) {
        for (const rel of changed) {
          if (!/\/(entities|concepts|topics)\/[^/]+\.md$/.test(rel)) continue;
          const required = [...new Set([...(preShaByPath.get(rel) ?? []), sha])];
          await ensureSourcesSection(wikiAbsPath(rel), required);
        }
      }

      // ★증강★: 원본 topic 끝에 '## 관련 분석' 링크 섹션을 ★코드가 멱등하게★ 붙인다(기존 섹션 제거 후 재작성).
      //   링크 목록은 이번에 만든 entities/concepts 페이지 제목에서 결정 → LLM의 append 변덕과 무관하게 항상 정확.
      if (apply && input.augment && input.preservePath) {
        const relatedPages = await loadPages(scope, ["entities", "concepts"]); // 적용 직후 디스크에서 최신 로드
        const section = buildRelatedSection(relatedPages, sha);
        if (section) {
          const topicAbs = wikiAbsPath(input.preservePath);
          try {
            let body = await fs.readFile(topicAbs, "utf8");
            const idx = body.indexOf("\n## 관련 분석");
            if (idx >= 0) body = body.slice(0, idx);
            body = body.replace(/\s+$/, "") + "\n\n" + section + "\n";
            await atomicWriteFile(topicAbs, body); // 원자적
            if (!changed.includes(input.preservePath)) changed.push(input.preservePath);
          } catch { /* 토픽 없음 → 건너뜀 */ }
        }
      }
      // 생성된 페이지에 분석 모델·토큰 footer 기록(적용된 경우만; 검토대기면 페이지 미생성이라 생략).
      if (apply) await stampAnalysisCost(changed, servedModel, usage.inputTokens, usage.outputTokens);
      // ★목차 표준화★ — LLM이 쓴 index.md를 코드로 일관 형식(룸 이름·개체/개념/주제·설명 보존) 재생성.
      //   룸마다 형식이 제각각이던 것 방지. best-effort(실패해도 인제스트는 진행).
      if (apply) { try { await regenerateIndex(scope); if (!changed.includes(`${scope}/index.md`)) changed.push(`${scope}/index.md`); } catch { /* skip */ } }
      const commitSha = await commitAll(
        apply ? `ingest(${scope}): ${input.title}` : `ingest-pending(${scope}): ${input.title} [검토대기]`,
        {
          sourceSha256: sha,
          sourceType: type,
          team: scope,
          confidence: data.confidence,
          gate: apply ? "AUTO_APPLIED" : "HUMAN_REVIEW",
          model: ingestModel,
        },
      );
      return { commitSha, changed: [rawRel, ...extra, ...changed] };
    });

    await prisma.ingestJob.update({
      where: { id: job.id },
      data: {
        status: apply ? "APPLIED" : "NEEDS_REVIEW",
        editSet: JSON.stringify(data),
        confidence: data.confidence,
        gate: apply ? "AUTO_APPLIED" : "HUMAN_REVIEW",
        commitSha,
      },
    });

    // ★검토 대기 알림★ (A-4) — 사람 확인이 필요한 결과면 그 scope 관리자에게 알림(검토 콘솔로). 알림 실패는 인제스트를 막지 않음.
    if (!apply) { try { await notifyNeedsReview(scope, job.id, input.title); } catch { /* 알림 실패 무시 */ } }

    await recordUsage({ userId: input.userId, scope, kind: "ingest", model: servedModel, inputTokens: usage.inputTokens, outputTokens: usage.outputTokens });

    // ★검색 임베딩 미리 워밍★ — 바뀐 지식 페이지를 백그라운드로 임베딩(검색의 콜드 캐시 지연 제거). 응답을 막지 않음.
    if (apply) {
      const pagePaths = changed.filter((p) => /\/(entities|concepts|topics|queries)\/[^/]+\.md$/.test(p));
      if (pagePaths.length) void (async () => {
        const wp: { path: string; content: string }[] = [];
        for (const rel of pagePaths) { try { wp.push({ path: rel, content: await fs.readFile(wikiAbsPath(rel), "utf8") }); } catch { /* 삭제됨 */ } }
        await warmPageEmbeddings(scope, wp);
      })();
      // ★검색 색인(Phase 2) 동기화★ — 바뀐 페이지를 wiki_doc에 반영(키워드 검색이 파일 스캔 없이 빠르게). 백그라운드.
      void syncWikiDocs(changed).catch(() => {});
    }

    return {
      status: apply ? "APPLIED" : "NEEDS_REVIEW",
      sourceId: source.id,
      jobId: job.id,
      commitSha,
      changedPaths: changed,
      confidence: data.confidence,
      needsHuman: data.needs_human,
      usedModel: servedModel,
      fallback: fallbackInfo, // 1순위 대체 시 {fromModel, reason} — 미대체면 undefined
    };
  } catch (err) {
    console.error(`[ingest] FAILED source=${source.id} scope=${scope} title="${input.title}": ${String(err)}`);
    // 실패한 자료는 '실패' 상태로 남겨 사용자에게 보이게 한다(흔적 없이 사라지지 않도록).
    // 같은 파일 재업로드 시에는 위 dedup 분기가 이 실패본을 정리하고 재인제스트한다.
    await prisma.ingestJob.update({
      where: { id: job.id },
      data: { status: "FAILED", attempts: { increment: 1 }, error: String(err) },
