  const yyyy = String(now.getFullYear());
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const rawExt = input.rawExt ?? "md";
  const rawRel = `raw/${scope}/${yyyy}/${mm}/${sha}.${rawExt}`;
  const stem = rawRel.replace(/\.[^.]+$/, "");
  const normalizedRel = hasText ? `${stem}.normalized.md` : null;

  const source = await prisma.source.create({
    data: {
      teamScope: scope, type, sha256: sha, title: input.title, rawPath: rawRel,
      uploadedBy: input.userId ?? null, anonymous: input.anonymous ?? false, mimeType: input.mimeType ?? null,
      byteSize: input.byteSize ?? input.rawBytes?.byteLength ?? Buffer.byteLength(text, "utf8"),
      originalName: input.originalName ?? null,
      extractor: input.extractor ?? null,
      extractStatus: input.extractStatus ?? null,
      normalizedPath: normalizedRel,
      provenance: JSON.stringify({ uploadedAt: now.toISOString(), staged: true, hasText, looksOrganized }),
    },
  });

  try {
    await withWikiWriteLock(async () => {
      const rawAbs = wikiAbsPath(rawRel);
      await fs.mkdir(path.dirname(rawAbs), { recursive: true });
      await fs.writeFile(rawAbs, input.rawBytes ?? text);
      if (input.assets?.length) {
        const assetsDir = wikiAbsPath(`${stem}.assets`);
        await fs.mkdir(assetsDir, { recursive: true });
        for (let i = 0; i < input.assets.length; i++) {
          const a = input.assets[i];
          const aext = a.mediaType.split("/")[1] || "png";
          await fs.writeFile(wikiAbsPath(`${stem}.assets/${String(i + 1).padStart(2, "0")}.${aext}`), a.bytes);
        }
      }
      if (normalizedRel) await fs.writeFile(wikiAbsPath(normalizedRel), input.normalizedText!, "utf8");
      return commitAll(`stage(${scope}): ${input.title} [분석대기]`, { sourceSha256: sha, sourceType: type, team: scope, gate: "STAGED" });
    });
  } catch (err) {
    await prisma.source.delete({ where: { id: source.id } }).catch(() => {});
    throw err;
  }
  return { status: "PENDING", sourceId: source.id, extractStatus: input.extractStatus ?? undefined, hasText, looksOrganized };
}

/**
 * [분석] — 스테이징된 원본을 ★실제 LLM 인제스트★. 보관된 raw/normalized를 다시 읽어 ingestText에 넘긴다.
 * ingestText의 dedup이 APPLIED 잡 없는 스테이징 소스를 정리 후 새로 만들므로 중복 없이 교체된다.
 */
export async function analyzeSource(sourceId: number, opts: { model?: string; provider?: string; think?: boolean; signal?: AbortSignal; diarize?: boolean; meeting?: boolean }): Promise<IngestResult> {
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) throw new Error("자료를 찾을 수 없습니다.");
  const scope = source.teamScope;
  const rawBytes = await fs.readFile(wikiAbsPath(source.rawPath));
  const rawExt = (source.rawPath.split(".").pop() || "md").toLowerCase();
  // ★전사(음성·영상) 소스는 무조건 회의록으로 처리★ — 토글 제거(사용자 결정). PDF·이미지·텍스트엔 무영향.
  const meeting = isTranscribedExtractor(source.extractor);
  const base = {
    scope, title: source.title, userId: source.uploadedBy, rawBytes, rawExt,
    mimeType: source.mimeType ?? undefined, byteSize: source.byteSize ?? undefined, originalName: source.originalName ?? undefined,
    model: opts.model, provider: opts.provider, think: opts.think, signal: opts.signal, meeting,
  };
  const provider = base.provider ?? providerFor("ingest");
  const isImg = source.type === "IMAGE" || ["png", "jpg", "jpeg", "gif", "webp"].includes(rawExt);
  const isPdf = source.type === "PDF" || rawExt === "pdf";

  // 원본이 이미 위키 topic으로 보존돼 있으면(=‘원본 그대로 추가’ 후 분석) → ★증강 모드★(강한 tier만):
  //   원본은 요약·대체하지 않고 entities/concepts 그래프만 추가 + 원본엔 '관련 분석' 링크만 덧붙인다.
  let augment = false; let preservePath: string | undefined;
  if (promptTier(provider) === "strong") {
    const slug = slugifyTitle(source.title) || `note-${source.id}`;
    const rawTopicRel = `${scope}/topics/${slug}.md`;
    try { await fs.access(wikiAbsPath(rawTopicRel)); augment = true; preservePath = rawTopicRel; } catch { /* 원본 topic 없음 → 일반 분석 */ }
  }

  // ── PDF: ★표 보존 우선★ ──
  //   (1) 매번 ★새로 추출★해 표 행·열 복원본을 쓴다(업로드 때 저장된 납작한 사이드카에 고착되지 않게).
  //   (2) 문서첨부 지원 공급자(Gemini/Claude)면 ★원본 PDF를 직접 첨부★해 모델이 표·레이아웃을 직접 읽게 한다
  //       (추출 텍스트는 보조). 표 많은 PDF가 '요약만' 되던 문제를 근본 해결.
  if (isPdf) {
    let extracted = "";
    try {
      const ex = await extractAsset(rawBytes, source.originalName ?? `${source.title}.pdf`, source.mimeType ?? "application/pdf");
      if (ex.text?.trim()) extracted = ex.text;
    } catch { /* 추출 실패 → 아래 사이드카/네이티브 폴백 */ }
    if (!extracted && source.normalizedPath) {
      try { extracted = await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8"); } catch { /* */ }
    }
    if (supportsNativeDocs(provider)) {
      const aid = extracted ? extracted.slice(0, 16000) : ""; // 보조 추출 텍스트(토큰 절약 위해 상한)
      const caption = aid
        ? `이 PDF 원본을 첨부합니다(표·레이아웃 포함). 표·수치는 ★첨부 원본을 우선★ 근거로 빠짐없이 정리하세요. 아래는 보조 추출 텍스트(표가 일부 깨졌을 수 있음):\n\n${aid}`
        : `PDF 파일명: ${source.originalName ?? source.title}. 첨부한 PDF를 분석해 표·수치를 빠짐없이 위키 지식으로 정리하세요.`;
      return ingestText({ ...base, type: "PDF", rawExt: "pdf", extractor: "pdf-native", extractStatus: "FULL",
        text: caption,
        documents: [{ mediaType: "application/pdf", dataBase64: rawBytes.toString("base64") }],
        augment, preservePath });
    }
    if (extracted) {
      // 텍스트 전용 공급자(ollama/groq 등): 개선된 추출 텍스트로 인제스트.
      return ingestText({ ...base, type: "PDF", text: extracted, extractor: source.extractor ?? "pdfjs-layout",
        extractStatus: "FULL", normalizedText: extracted, augment, preservePath });
    }
    // 추출 전무(스캔 PDF 등) → 네이티브 첨부 폴백.
    return ingestText({ ...base, type: "PDF", rawExt: "pdf", extractor: "pdf-vision", extractStatus: "FULL",
      text: `PDF 파일명: ${source.originalName ?? source.title}. 이 문서를 분석해 정리하세요.`,
      documents: [{ mediaType: "application/pdf", dataBase64: rawBytes.toString("base64") }],
      augment, preservePath });
  }

  // ── 이미지: 비전 첨부 ──
  if (isImg) {
    const imgMime = source.mimeType || sniffImageMime(rawBytes) || "image/png";
    return ingestText({ ...base, type: "IMAGE", extractor: "vision", extractStatus: "FULL",
      text: `이미지 파일명: ${source.originalName ?? source.title}. 이 이미지를 분석해 핵심 정보를 위키 지식으로 정리하세요.`,
      images: [{ mediaType: imgMime, dataBase64: rawBytes.toString("base64") }] });
  }

  // ── 음성·영상 + 화자 구분 요청 → ★raw를 Gemini로 재전사★(화자1/2 라벨). 업로드 땐 Groq 평문이라 여기서 다시.
  //   diarize 아닐 땐 아래 normalizedPath(업로드 전사문)를 그대로 쓴다(추가형 — 기존 흐름 무영향).
  if (opts.diarize && isTranscribedExtractor(source.extractor)) {
    try {
      const r = await transcribe(rawBytes, source.originalName ?? source.title, source.mimeType ?? "audio/mpeg", { diarize: true });
      if (r.text.trim() && r.quality !== "none") {
        return ingestText({ ...base, type: source.type, text: r.text, extractor: r.extractor, extractStatus: "FULL", normalizedText: r.text, augment, preservePath });
      }
    } catch { /* 재전사 실패 → 아래 저장된 전사문으로 폴백 */ }
  }

  // ── 그 외(텍스트형 docx/xlsx/…): 저장된 정규화 사이드카 ──
  if (source.normalizedPath) {
    const normalized = await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8");
    return ingestText({ ...base, type: source.type, text: normalized, extractor: source.extractor ?? undefined,
      extractStatus: source.extractStatus ?? undefined, normalizedText: normalized, augment, preservePath });
  }
  throw new Error("분석할 텍스트가 없습니다(비전 모델이 필요한 형식). Gemini/Claude 모델로 다시 시도하세요.");
}

/**
 * [원본 그대로] — ★LLM 없이(토큰 0)★ 텍스트 원본을 위키 페이지로 직접 파일링한다. 이미 정리된 문서용.
 * topics/<slug>.md로 저장(쿼리 로드 대상) + index 한 줄 추가 + APPLIED 잡 생성("반영됨"). recordUsage 없음.
 */
export async function fileSourceAsIs(sourceId: number): Promise<IngestResult> {
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) throw new Error("자료를 찾을 수 없습니다.");
  await assertWikiReady();
  const scope = source.teamScope;
  let body = source.normalizedPath
    ? await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8")
    : (await fs.readFile(wikiAbsPath(source.rawPath))).toString("utf8");
  body = body.trim();
  if (!body) throw new Error("텍스트가 없어 '원본 그대로' 추가를 할 수 없습니다. [분석]을 사용하세요.");

  const slug = slugifyTitle(source.title) || `note-${source.id}`;
  const pageRel = `${scope}/topics/${slug}.md`;
  const pageContent = hasFrontmatter(body)
    ? body + "\n"
    : frontmatterOf({
        title: source.title.replace(/\n/g, " ").slice(0, 80), type: "note", scope,
        sources: JSON.stringify([source.sha256]), updated: kstStamp(),
      }) + "\n" + body + "\n";

  // index.md는 아래 regenerateIndex가 디스크에서 자동 생성하므로 edits에 넣지 않는다(누락·형식 드리프트 방지).
  const editSet: EditSet = {
    edits: [
      { op: "create", path: pageRel, content: pageContent },
    ],
    log_entry: `원본 그대로 추가(분석 없음): ${source.title}`,
    confidence: 1,
  };

  const { commitSha, changed } = await withWikiWriteLock(async () => {
    const changed = await applyEditSet(scope, editSet);
    try { await regenerateIndex(scope); if (!changed.includes(`${scope}/index.md`)) changed.push(`${scope}/index.md`); } catch { /* skip */ } // 목차 표준화
    const commitSha = await commitAll(`import(${scope}): ${source.title} [원본그대로]`, { sourceSha256: source.sha256, sourceType: source.type, team: scope, gate: "RAW_IMPORT" });
    return { commitSha, changed };
  });

  const job = await prisma.ingestJob.create({
    data: { sourceId: source.id, teamScope: scope, status: "APPLIED", model: "(분석없음)", gate: "RAW_IMPORT", confidence: 1, commitSha },
  });
  void syncWikiDocs(changed).catch(() => {}); // ★검색 색인 동기★
  return { status: "APPLIED", sourceId: source.id, jobId: job.id, commitSha, changedPaths: changed, confidence: 1, usedModel: "원본 그대로(분석 안 함)" };
}

// ★검토 대기(NEEDS_REVIEW) 알림★ (A-4) — 사람 확인이 필요한 분석 결과를 그 scope 관리자에게 알린다(검토 콘솔로).
//   수신자: 프로젝트 룸=OWNER, 공통=ADMIN, 개인=본인. jobId·수신자로 멱등(재시도 시 중복 없음).
async function notifyNeedsReview(scope: string, jobId: number, title: string): Promise<void> {
  let managers: number[] = [];
  if (scope.startsWith("project-")) {
    const project = await prisma.project.findUnique({ where: { slug: scope.slice("project-".length) }, select: { id: true } });
    if (project) managers = (await prisma.projectMembership.findMany({ where: { projectId: project.id, role: "OWNER" }, select: { userId: true } })).map((m) => m.userId);
  } else if (scope.startsWith("personal/")) {
    const uid = Number(scope.slice("personal/".length));
    if (Number.isInteger(uid)) managers = [uid];
  } else {
    managers = (await prisma.user.findMany({ where: { role: "ADMIN" }, select: { id: true } })).map((u) => u.id);
  }
  for (const userId of managers) {
    await createNotification({
      userId, type: "REVIEW", teamScope: scope,
      title: `검토 대기 자료: ${title}`,
      body: "AI 분석 결과에 사람 확인이 필요해요. 검토 콘솔에서 승인하거나 수정해 주세요.",
      linkPath: "/review",
      dedupKey: `review:${jobId}:${userId}`,
    });
  }
}

