// 업로드/인제스트 dedup 판정(순수·테스트 대상). 같은 sha의 기존 소스가 ★재처리를 막는 활성 중복★인지.
// ★아카이브(삭제)된 소스는 막지 않는다★ — 자료/위키에서 삭제한 뒤 같은 파일을 다시 올리면 새로 처리되게
// (삭제했는데 재업로드 시 '중복(건너뜀)'이 뜨던 버그 수정). appliedJobCount=분석(APPLIED) 잡 수:
// 0이면 분석 전(스테이지/실패) → 막지 않고 교체.
export function isBlockingDup(dup: { archivedAt: Date | null; appliedJobCount: number } | null): boolean {
  return !!dup && dup.archivedAt == null && dup.appliedJobCount > 0;
}

