// [처리 시작] — 대기(staged) 항목을 순차 처리(위키는 단일 라이터). 끝나면 목록·트리 갱신.
async function runStaged() {
  if (busy) return;
  const qScope = scope; // ★처리를 시작한 룸★ 고정(중간에 룸을 옮겨도 busy는 이 룸에만)
  const todo = staged.filter((s) => s.status === "staged" && s.sourceId);
  if (!todo.length) return;
  // ★유료(종량 과금) 경고★ — 선택/자동추천된 분석 모델 중 OpenAI·Claude API가 있으면 확인.
  if (uploadMode !== "raw") {
    const usesPaid = todo.some((it) => isPaidProvider(analyzeModels.find((m) => m.id === (modelUserPicked ? analyzeModelId : (it.reco?.model ?? analyzeModelId)))?.provider));
    if (usesPaid && !await confirmDialog("선택/추천된 분석 모델 중 ★사용량만큼 과금★되는 유료 모델(OpenAI·Claude API)이 있습니다. 계속할까요?")) return;
  }
  setBusyFor(qScope, true); setErr(null);
  try {
    for (const it of todo) {
      // 표시 모델: 직접 고름이면 그 모델, 자동이면 ★서버가 고를 모델(업로드 시 reco)★.
      const procM = modelUserPicked ? analyzeModelId : (it.reco?.model ?? analyzeModelId);
      const ctrl = new AbortController(); // 항목별 취소(이 항목만 중단하고 다음 항목은 계속)
      const startedAt = Date.now();
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: "running", at: startedAt, ctrl, note: uploadMode === "raw" ? "추가 중…" : (procM ? `분석 중… · ${modelLabel(procM)}` : "분석 중…") } : x)));
      // ★최근 자료(sources) 행도 '처리 중'으로★ — 대기목록과 싱크(같은 자료가 한쪽 '분석중'·다른쪽 '분석 대기'로 어긋나던 문제).
      if (it.sourceId) setActing((a) => new Map(a).set(it.sourceId!, { label: procM ? modelLabel(procM) : "", at: startedAt, ctrl }));
      let r: { ok: boolean; note: string };
      try {
        r = await runProcess(it.sourceId!, it.hasText, ctrl.signal);
      } catch (e) {
        const aborted = e instanceof Error && e.name === "AbortError";
        r = { ok: false, note: aborted ? "분석 취소됨" : `오류: ${toUserMessage(e)}` };
      }
      if (it.sourceId) { markDuration(it.sourceId, Date.now() - startedAt); setActing((a) => { const c = new Map(a); c.delete(it.sourceId!); return c; }); } // 소요 기록 + '처리 중' 해제(load로 최종 상태 반영)
      setStaged((p) => p.map((x) => (x.key === it.key ? { ...x, status: r.ok ? "done" : "error", at: undefined, ctrl: undefined, note: r.note } : x)));
      // ★각 항목이 끝나는 즉시★ 최근 자료·위키 갱신 — 전부 끝날 때까지 기다리지 않게(완료분이 바로 보임).
      await load();
      onDataChanged?.();
    }
  } finally {
    setBusyFor(qScope, false);
    await load();
    onDataChanged?.(); // 최종 갱신(위키 트리/리더)
  }
}

