// docs/PLAN-large-files-and-chunking.md §10.1·§10.5.
export async function register() {
  // ★edge 런타임에서도 실행되므로 nodejs 가드 필수★(pg-boss는 node 전용). 가드 없으면 edge 번들이 깨진다.
