// ★서버측 처리 중(RUNNING/APPLYING) 항목이 있으면 자동 폴링★ — 취소·완료가 수동 새로고침 없이 반영되게.
//   (취소=abort는 즉시 보내지만 서버가 상태를 '취소됨'으로 바꾸는 덴 시간차가 있어, 폴링으로 따라잡는다.)
const anyServerProc = sources.some((s) => s.status === "RUNNING" || s.status === "APPLYING");
useEffect(() => {
  if (!anyServerProc) return;
  const t = setInterval(() => { void load(); }, 2000);
  return () => clearInterval(t);
}, [anyServerProc, load]);
// 서버 상태가 더 이상 처리중이 아니면 '취소 중' 표시 해제(취소 확정 → 실패/완료 박스로 전환).
useEffect(() => {
  setCanceling((c) => {
    if (c.size === 0) return c;
    const next = new Set([...c].filter((id) => { const s = sources.find((x) => x.id === id); return !!s && (s.status === "RUNNING" || s.status === "APPLYING"); }));
    return next.size === c.size ? c : next;
  });
}, [sources]);

