const nextConfig = {
  // 배포(Docker/k8s)용 독립 실행 번들 — node_modules 추적분만 포함한 작은 런타임 이미지.
  output: "standalone",

  // 인제스트 워커가 wiki-runtime git에 simple-git/child_process로 접근하므로
  // 서버 컴포넌트 외부 패키지로 번들에서 제외한다.
  serverExternalPackages: ["simple-git", "@prisma/client", "pdfjs-dist", "mammoth", "xlsx", "officeparser", "word-extractor", "jszip", "jschardet", "iconv-lite"],

  // 개발 공유(같은 사내망에서 동료가 LAN IP로 접속) 허용.
