import { describe, it, expect } from "vitest";
import { weekKey, scopeIdFromTeamScope } from "../lib/jobs/stale";

// H2 오래됨 알림 잡의 순수 헬퍼 — 주차 dedup 키·scope id 변환.
describe("weekKey", () => {
  const base = new Date("2026-06-24T00:00:00Z");
  it("같은 시각은 같은 키", () => {
    expect(weekKey(base)).toBe(weekKey(base));
  });
  it("7일 뒤는 반드시 다른 버킷(주 1회 dedup)", () => {
    expect(weekKey(new Date(base.getTime() + 7 * 86_400_000))).not.toBe(weekKey(base));
  });
  it("몇 시간 차이는 같은 버킷", () => {
    expect(weekKey(new Date(base.getTime() + 5 * 3_600_000))).toBe(weekKey(base));
  });
});

describe("scopeIdFromTeamScope", () => {
  it("personal/<n> → personal:<n>(딥링크 room 파라미터용)", () => {
    expect(scopeIdFromTeamScope("personal/7")).toBe("personal:7");
    expect(scopeIdFromTeamScope("personal/123")).toBe("personal:123");
  });
  it("common·project는 그대로", () => {
    expect(scopeIdFromTeamScope("common")).toBe("common");
    expect(scopeIdFromTeamScope("project-acme")).toBe("project-acme");
  });
});

