import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { analyzeSource, fileSourceAsIs } from "@/lib/ingest";
import { resolveIngestModel, recommendIngestModel } from "@/lib/models";
import { isTranscribedExtractor } from "@/lib/stt";
import { checkDailyBudget, budgetExceededMessage } from "@/lib/cost";
import { beginInflight, endInflight } from "@/lib/inflight";
import { enqueueIngest } from "@/lib/queue";

// 스테이징된 자료를 ★실행★ — mode:"llm"=LLM 분석(토큰), mode:"raw"=원본 그대로 파일링(토큰 0).
export const runtime = "nodejs";
export const maxDuration = 600; // 무거운 자료를 추론 모델(claude/codex)이 분석할 때 길어질 수 있음(타임아웃 600초와 정렬)

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source) return NextResponse.json({ error: "자료를 찾을 수 없습니다." }, { status: 404 });
  // ACL: 접근 가능한 scope의 자료만(인제스트 적용 강제지점).
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(source.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });

  const { mode, model, reanalyze, diarize, meeting } = await req.json().catch(() => ({}));
  try {
    if (mode === "raw") {
      // 토큰 0 — 이미 정리된 텍스트를 위키 페이지로 직접 파일링.
      return NextResponse.json(await fileSourceAsIs(id));
    }
    // mode "llm"(기본): 비용 상한 체크 후 실제 LLM 인제스트.
    const budget = await checkDailyBudget(user.id, source.teamScope);
    if (budget.exceeded) {
      return NextResponse.json({ error: budgetExceededMessage(budget) }, { status: 429 });
    }
    // ★다시 분석★: 이미 분석된 자료를 재분석할 때, 기존 잡을 지워 ingestText의 dedup(SKIPPED_DUP)을 우회해
    //   실제 재인제스트가 돌게 한다. (증강 재실행은 원본의 '관련 분석' 섹션을 멱등하게 갱신.)
    if (reanalyze) await prisma.ingestJob.deleteMany({ where: { sourceId: id } });
    // 모델 선택: 사용자가 셀렉트박스에서 ★직접 고른 경우만★ 그 모델을 쓰고, 아니면(자동) ★자료 형식 기반 추천★.
    //   → 신규 업로드뿐 아니라 ★재처리·원본추가★도 자료(확장자)에 맞는 최적 모델로 자동 분석된다(PDF·표·텍스트별).
    let picked: { model: string; provider: string; think: boolean };
    if (typeof model === "string" && model) {
      picked = await resolveIngestModel(model);
    } else {
      // ★전사 소스(extractor groq-/gemini-)는 byteSize가 '오디오 바이트'라 텍스트 길이가 아님 → 크기 휴리스틱 제외★
      //   (안 그러면 모든 음성이 '큰 자료'로 오인돼 유료 추론 모델로 자동 라우팅됨). 표시 추천과도 일치.
      const transcribed = isTranscribedExtractor(source.extractor);
      const reco = await recommendIngestModel({ type: source.type, chars: transcribed ? undefined : (source.byteSize ?? undefined), transcribed });
      picked = { model: reco.model, provider: reco.provider, think: false };
    }
    // ★L2 비동기 큐(ship-dark)★: INGEST_ASYNC=true면 무거운 분석을 백그라운드 워커로 넘기고 즉시 반환한다.
    //   QUEUED 추적 잡을 만들어 enqueue → 워커가 reuse 모드로 in-place 갱신(QUEUED→RUNNING→APPLIED).
    //   enqueue 실패(boss 없음 등)면 추적 잡을 지우고 ★아래 동기 경로로 폴백★(플래그 OFF와 동일 동작).
    if (process.env.INGEST_ASYNC === "true") {
      const queuedJob = await prisma.ingestJob.create({
        data: { sourceId: id, teamScope: source.teamScope, status: "QUEUED", model: picked.model, phase: "대기 중" },
      });
      const ok = await enqueueIngest({
        ingestJobId: queuedJob.id, sourceId: id,
        model: picked.model, provider: picked.provider, think: picked.think,
        diarize: !!diarize, meeting: !!meeting, userId: user.id,
      });
      if (ok) return NextResponse.json({ queued: true, jobId: queuedJob.id });
      await prisma.ingestJob.delete({ where: { id: queuedJob.id } }).catch(() => {}); // 폴백 전 추적 잡 정리
    }
    // ★원본 보존 + 그래프 증강★: 원본이 이미 topic으로 보존돼 있으면 analyzeSource가 증강 모드로 처리(원본 유지,
    //   entities/concepts만 추가, 원본엔 링크만 덧붙임).
    // 취소: req.signal(클라 abort) + 서버측 in-flight 컨트롤러를 함께 사용한다. nginx 뒤에서 req.signal이
    //   발화하지 않아도, /cancel 엔드포인트가 이 컨트롤러를 직접 abort해 LLM 서브프로세스까지 중단을 전파한다.
    const inflight = beginInflight("analyze", id, user.id, source.teamScope, req.signal);
    try {
      const result = await analyzeSource(id, { model: picked.model, provider: picked.provider, think: picked.think, signal: inflight.signal, diarize: !!diarize, meeting: !!meeting });
      return NextResponse.json(result);
