import { describe, it, expect } from "vitest";
import { shouldRunAsync } from "../lib/queue";

// L2 비동기 큐의 ★ship-dark 게이트★(docs/PLAN-large-files-and-chunking §10). 순수 결정 함수만 테스트.
//   핵심 불변: 플래그 OFF면 무조건 동기(false). raw 모드는 켜져 있어도 동기.
describe("shouldRunAsync (ship-dark 게이트)", () => {
  it("기본(미설정)은 OFF — 항상 동기", () => {
    expect(shouldRunAsync({}, "llm")).toBe(false);
    expect(shouldRunAsync({ INGEST_ASYNC: undefined }, "llm")).toBe(false);
  });
  it("INGEST_ASYNC가 정확히 'true'일 때만 ON", () => {
    expect(shouldRunAsync({ INGEST_ASYNC: "true" }, "llm")).toBe(true);
    expect(shouldRunAsync({ INGEST_ASYNC: "1" }, "llm")).toBe(false);
    expect(shouldRunAsync({ INGEST_ASYNC: "TRUE" }, "llm")).toBe(false);
    expect(shouldRunAsync({ INGEST_ASYNC: "false" }, "llm")).toBe(false);
  });
  it("raw 모드(토큰0·빠름)는 플래그 ON이어도 항상 동기", () => {
    expect(shouldRunAsync({ INGEST_ASYNC: "true" }, "raw")).toBe(false);
  });
  it("mode 미지정(기본 llm 취급)도 플래그 ON이면 비동기", () => {
    expect(shouldRunAsync({ INGEST_ASYNC: "true" }, undefined)).toBe(true);
  });
});

