// ── L2 비동기 워커의 잡 처리 함수 ────────────────────────────────────────────────
// docs/PLAN-large-files-and-chunking.md §10.2. ★엔드포인트(동기)와 워커(비동기)가 같은 함수★를
//   쓰도록 분석 실행을 한 곳에 모은다 — 여기선 analyzeSource를 ★잡 reuse 모드★로 호출한다.
//   reuse 모드(input.jobId): ingestText가 source/job을 ★삭제·재생성하지 않고 in-place 갱신★ →
//   sourceId·jobId가 안정 → pg-boss 재시도/만료가 멱등하게 같은 잡을 다시 처리할 수 있다(§9.1).
import { prisma } from "./db";
import { analyzeSource } from "./ingest";
import type { IngestJobPayload } from "./queue";

// 워커 핸들러의 실제 처리. throw하면 pg-boss가 재시도(retryLimit/backoff)·만료복구(expireInSeconds)한다.
export async function processIngestJob(payload: IngestJobPayload): Promise<void> {
  const { ingestJobId, sourceId } = payload;
  // 추적 잡이 사라졌으면(취소·정리) 더 할 일 없음 — 재시도해도 무의미하므로 조용히 종료.
  const job = await prisma.ingestJob.findUnique({ where: { id: ingestJobId } });
  if (!job) { console.log(`[queue] job ${ingestJobId} 없음(취소됨?) → 스킵`); return; }
  const source = await prisma.source.findUnique({ where: { id: sourceId } });
  if (!source) {
    // 자료가 사라짐 → 처리 불가. 추적 잡을 정리하고 종료(무한 재시도 방지).
    await prisma.ingestJob.update({ where: { id: ingestJobId }, data: { status: "FAILED", error: "자료가 삭제되었습니다." } }).catch(() => {});
    return;
  }

  // ★reuse 모드★: analyzeSource→ingestText가 이 추적 잡(QUEUED)을 RUNNING으로 바꾸고 끝에서 APPLIED/NEEDS_REVIEW로.
  //   삭제·재생성이 없으므로 진행률·상태가 같은 행에 연속 노출되고, 재시도 시 같은 잡을 다시 집는다.
  await analyzeSource(sourceId, {
    model: payload.model,
    provider: payload.provider,
    think: payload.think,
    diarize: payload.diarize,
    meeting: payload.meeting,
    jobId: ingestJobId, // ← reuse 트리거
  });
}

