// reuse 경로 실제 E2E: 스테이징 → QUEUED 잡 → processIngestJob(워커와 동일) → 단언 → 완전 원복.
import { config } from "dotenv"; config();
import { execSync } from "node:child_process";
const wiki = "wiki-runtime";
const head = execSync(`git -C ${wiki} rev-parse HEAD`).toString().trim();
const { PrismaClient } = await import("@prisma/client");
const prisma = new PrismaClient();
const ingest = await import("./lib/ingest.ts");
const { processIngestJob } = await import("./lib/ingest-run.ts");

const title = "큐테스트-원복대상-자료";
const md = "# 헬름스맨 배포도구\n\n헬름스맨(Helmsman)은 사내 배포 자동화 도구다. 주 담당자는 박민수이며, 롤백과 카나리 배포를 지원한다.\n";
let sourceId = 0, jobId = 0, changed: string[] = [];
try {
  const staged = await ingest.storeForAnalysis({ scope: "common", title, text: md, normalizedText: md, type: "MD", rawExt: "md", userId: null });
  sourceId = staged.sourceId;
  console.log("staged:", staged.status, "sourceId:", sourceId, "hasText:", staged.hasText);

  const job = await prisma.ingestJob.create({ data: { sourceId, teamScope: "common", status: "QUEUED", model: "gemini-2.5-flash", phase: "대기 중" } });
  jobId = job.id;
  console.log("QUEUED job:", jobId);

  // ★워커가 하는 것과 동일★ — reuse 모드(jobId)로 in-place 처리
  await processIngestJob({ ingestJobId: jobId, sourceId, model: "gemini-2.5-flash", provider: "gemini", userId: null });
  await new Promise((r) => setTimeout(r, 1500)); // 백그라운드 색인/임베딩 정착

  const after = await prisma.ingestJob.findUnique({ where: { id: jobId } });
  const src = await prisma.source.findUnique({ where: { id: sourceId } });
  changed = execSync(`git -C ${wiki} diff --name-only ${head} HEAD`).toString().trim().split("\n").filter(Boolean);
  const pages = changed.filter((p) => /common\/(entities|concepts|topics)\/.+\.md$/.test(p));
  console.log("── 결과 ──");
  console.log("job in-place 상태:", after?.status, "| 같은 잡 id 유지:", after?.id === jobId);
  console.log("소스 id 안정(삭제·재생성 없음):", !!src && src.id === sourceId, "| id:", src?.id, "(원본", sourceId + ")");
  console.log("생성된 지식 페이지:", pages.length, pages.slice(0, 8));
  const ok = (after?.status === "APPLIED" || after?.status === "NEEDS_REVIEW") && !!src && src.id === sourceId && after?.id === jobId && pages.length > 0;
  console.log(ok ? "✅ PASS: reuse 경로 정상 — 잡 in-place·소스 id 안정·페이지 생성" : "⚠️ REVIEW 필요(위 값 확인)");
} catch (e) {
  console.log("ERROR:", String(e).split("\n").slice(0, 3).join(" | "));
} finally {
  // ★완전 원복★ — 위키 git을 사전 HEAD로, DB 테스트 행 삭제, 검색색인/임베딩 정리(테스트 흔적 0).
  execSync(`git -C ${wiki} reset --hard ${head}`);
  execSync(`git -C ${wiki} clean -fd`);
  if (changed.length) {
    const pagePaths = changed.filter((p) => p.endsWith(".md") && !p.startsWith("raw/"));
    await prisma.wikiDoc.deleteMany({ where: { path: { in: pagePaths } } }).catch(() => {});
    await prisma.pageEmbedding.deleteMany({ where: { path: { in: pagePaths } } }).catch(() => {});
  }
  if (jobId) await prisma.ingestJob.deleteMany({ where: { id: jobId } }).catch(() => {});
  if (sourceId) await prisma.source.deleteMany({ where: { id: sourceId } }).catch(() => {});
  // 혹시 이름으로 남은 테스트 소스/잡(있다면) 정리
  const leftover = await prisma.source.findMany({ where: { title }, select: { id: true } });
  for (const s of leftover) { await prisma.ingestJob.deleteMany({ where: { sourceId: s.id } }); await prisma.source.delete({ where: { id: s.id } }); }
  console.log("🧹 원복: wiki reset", head.slice(0, 7), "+ DB/색인 정리 완료. clean?", execSync(`git -C ${wiki} status --porcelain`).toString().trim() === "" ? "YES" : "NO");
}
process.exit(0);

