// reuse 경로 실제 E2E — 격리 위키(WIKI_REPO_PATH=임시)·고유 scope. 실제 wiki-runtime/common 무관.
import { config } from "dotenv";
config(); // dotenv는 ★기존 env 미덮어씀★ → 외부에서 export한 WIKI_REPO_PATH 유지
console.log("WIKI_REPO_PATH =", process.env.WIKI_REPO_PATH);
const { PrismaClient } = await import("@prisma/client");
const prisma = new PrismaClient();
const ingest = await import("./lib/ingest.ts");
const { processIngestJob } = await import("./lib/ingest-run.ts");

const SCOPE = "e2e-async-test";
const title = "비동기E2E-임시자료";
const md = "# 헬름스맨 배포도구\n\n헬름스맨(Helmsman)은 사내 배포 자동화 도구다. 주 담당자는 박민수이며, 롤백·카나리 배포를 지원한다. 슬랙 알림과 연동된다.\n";
let sourceId = 0, jobId = 0;
try {
  const staged = await ingest.storeForAnalysis({ scope: SCOPE, title, text: md, normalizedText: md, type: "MD", rawExt: "md", userId: null });
  sourceId = staged.sourceId;
  console.log("1) staged:", staged.status, "sourceId:", sourceId, "hasText:", staged.hasText);

  const job = await prisma.ingestJob.create({ data: { sourceId, teamScope: SCOPE, status: "QUEUED", model: "gemini-2.5-flash", phase: "대기 중" } });
  jobId = job.id;
  console.log("2) QUEUED job:", jobId);

  console.log("3) processIngestJob 실행(워커와 동일·reuse 모드)...");
  await processIngestJob({ ingestJobId: jobId, sourceId, model: "gemini-2.5-flash", provider: "gemini", userId: null });
  await new Promise((r) => setTimeout(r, 1500)); // 백그라운드 색인 정착

  const after = await prisma.ingestJob.findUnique({ where: { id: jobId } });
  const src = await prisma.source.findUnique({ where: { id: sourceId } });
  const docs = await prisma.wikiDoc.findMany({ where: { scope: SCOPE }, select: { path: true } });
  console.log("── 결과 ──");
  console.log("• 잡 in-place 상태:", after?.status, "| 같은 잡 id 유지:", after?.id === jobId);
  console.log("• 소스 id 안정(삭제·재생성 X):", !!src && src.id === sourceId, "| id:", src?.id, "(원본", sourceId + ")");
  console.log("• 생성된 지식 페이지:", docs.length);
  for (const d of docs.slice(0, 10)) console.log("   -", d.path);
  // 원본 sha가 페이지 '## 출처'에 보존됐는지(reuse가 메타 갱신 정상)
  const fs = await import("node:fs");
  const { wikiAbsPath } = await import("./lib/wiki/paths.ts");
  let shaOk = false;
  if (src) for (const d of docs) { try { if ((await fs.promises.readFile(wikiAbsPath(d.path), "utf8")).includes(src.sha256)) { shaOk = true; break; } } catch { /* */ } }
  console.log("• 원본 sha 출처 보존:", shaOk);
  const ok = (after?.status === "APPLIED" || after?.status === "NEEDS_REVIEW") && !!src && src.id === sourceId && after?.id === jobId && docs.length > 0;
  console.log(ok ? "✅ PASS: reuse 경로 정상 — 잡 in-place·소스 id 안정·페이지 생성" : "⚠️ REVIEW 필요");
} catch (e) {
  console.log("❌ ERROR:", String(e).split("\n").slice(0, 5).join(" | "));
} finally {
  // DB 정리(고유 scope 전량) — 위키 파일은 격리 임시 repo라 bash에서 rm -rf.
  await prisma.wikiDoc.deleteMany({ where: { scope: SCOPE } }).catch(() => {});
  await prisma.pageEmbedding.deleteMany({ where: { scope: SCOPE } }).catch(() => {});
  await prisma.tokenUsage.deleteMany({ where: { teamScope: SCOPE } }).catch(() => {});
  await prisma.ingestJob.deleteMany({ where: { teamScope: SCOPE } }).catch(() => {});
  await prisma.source.deleteMany({ where: { teamScope: SCOPE } }).catch(() => {});
  console.log("🧹 DB 정리 완료(scope", SCOPE + ")");
}
process.exit(0);

