export default function AppShell({ user, scopes, archivedScopes = [] }: { user?: Me; scopes: AllowedScope[]; archivedScopes?: AllowedScope[] }) {
  const me: Me = user ?? { name: "사용자", dept: "사내", initials: "U" };
  const router = useRouter();
  const [scope, setScope] = useState(scopes[0]?.id ?? "common");
  const [tab, setTab] = useState<string>("chat");
  const [navOpen, setNavOpen] = useState(false); // 폰: 사이드바 드로어 열림(≤640px)
  const tabByScope = useRef<Record<string, string>>({}); // 룸(scope)별 마지막 메인 탭(자료/질의/위키)
  const [restoring, setRestoring] = useState(false); // 아카이브 룸 복원 진행 중
  const [dark, setDark] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [inviteOpen, setInviteOpen] = useState(false);
  const [wikiTarget, setWikiTarget] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);
  const [usageOpen, setUsageOpen] = useState(false);
  const [feedbackOpen, setFeedbackOpen] = useState(false);
  const [insightsOpen, setInsightsOpen] = useState(false);
  const [secretsOpen, setSecretsOpen] = useState(false);
  // 관리자가 설정 모달에서 모델을 토글할 수 있으므로, 모달이 닫힐 때 모델 목록을 재조회하도록 신호.
  const [modelsRev, setModelsRev] = useState(0);
  // 자료↔위키 교차 갱신 신호 — 자료 탭이 페이지를 추가/분석하거나, 위키 배너가 [AI로 분석]하면 +1.
  // 두 탭이 항상 마운트돼 있어 새로고침 없이 서로의 목록/트리를 재조회한다(③ 해결).
  const [dataRev, setDataRev] = useState(0);
  const prevAccountOpen = useRef(false);
  useEffect(() => {
    if (prevAccountOpen.current && !accountOpen) setModelsRev((v) => v + 1);
    prevAccountOpen.current = accountOpen;
  }, [accountOpen]);
  // 서버가 쿠키로 적용한 테마와 동기화(초기 깜빡임 방지).
  useEffect(() => { setDark(document.documentElement.classList.contains("dark")); }, []);

  // ★현재 룸(scope) 영속화★ — 새로고침해도 보던 룸 유지(기본 'common'으로 안 돌아감).
  //   여전히 접근 가능한 scope일 때만 복원(나간 룸·접근 불가면 기본값). 하이드레이션 안전 위해 mount 후 복원.
  useEffect(() => {
    try {
      // ★초대 수락 등으로 ?room=<scope>를 달고 들어오면★ 그 룸으로 바로 이동(세션 복원보다 우선) + URL은 '/'로 정리.
      const all = [...scopes, ...archivedScopes];
      const sp = new URLSearchParams(window.location.search);
      const want = sp.get("room");
      const page = sp.get("page"); // ★알림 등 페이지 딥링크★ — ?room=<scope>&page=<위키경로>
      if (want && all.some((s) => s.id === want)) {
        setScope(want);
        if (page) { setTab("wiki"); setWikiTarget(page); } // 그 페이지를 위키 탭에서 바로 열기
        else if (archivedScopes.some((s) => s.id === want)) setTab("wiki"); // 아카이브 룸은 위키 읽기 전용
        window.history.replaceState(null, "", "/");
        return;
      }
      try { const tj = sessionStorage.getItem("llmwiki_tabs_v1"); if (tj) tabByScope.current = JSON.parse(tj) || {}; } catch { /* noop */ }
      const saved = sessionStorage.getItem("llmwiki_scope_v1");
      if (saved && all.some((s) => s.id === saved)) {
        if (saved !== scope) setScope(saved);
