    const claim = await prisma.ingestJob.updateMany({
      where: { id: jobId, status: "NEEDS_REVIEW" },
      data: { status: "APPLYING" },
    });
    if (claim.count !== 1) return NextResponse.json({ error: "이미 처리 중이거나 완료된 항목입니다." }, { status: 409 });

    let editSet: EditSet;
    try {
      editSet = JSON.parse(job.editSet || "{}") as EditSet;
    } catch {
