import { NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { applyEditSet, coercePath, type EditSet } from "@/lib/wiki/applyEditSet";
import { wikiAbsPath } from "@/lib/wiki/paths";
import { diffLines, allAdded, type LineDiff } from "@/lib/wiki/linediff";
import { assertWikiReady, commitAll, withWikiWriteLock } from "@/lib/wiki/repo";
import { regenerateIndex } from "@/lib/wiki/maintenance";
import { syncWikiDocs } from "@/lib/wiki/searchIndex";
import type { User } from "@prisma/client";

// 검토 항목 승인(편집셋 적용)·반려 + ★변경 미리보기(GET)★. docs/12 §6 (승인=단일 라이터 커밋, actor=승인자).
export const runtime = "nodejs";

// 승인 권한: ADMIN(전체) · 룸 OWNER(해당 룸) · 개인 scope 본인. common은 ADMIN만(REQ-ACL-007).
async function canReview(user: User, teamScope: string): Promise<boolean> {
  if (user.role === "ADMIN") return true;
  if (teamScope === `personal/${user.id}`) return true;
  if (teamScope.startsWith("project-")) {
    const project = await prisma.project.findUnique({ where: { slug: teamScope.slice("project-".length) } });
    if (project) {
      const m = await prisma.projectMembership.findUnique({
        where: { userId_projectId: { userId: user.id, projectId: project.id } },
      });
      if (m?.role === "OWNER") return true;
    }
  }
  return false;
}

// ── 변경 미리보기: 각 편집이 ★현재 위키 본문 대비★ 무엇을 추가/삭제하는지 줄 단위 diff로 반환 ──
//   create(기존 파일 있음)=전체 교체 → before/after diff, create(새 파일)·append=전부 추가.
export async function GET(_req: Request, { params }: { params: Promise<{ jobId: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const jobId = Number((await params).jobId);
  if (!Number.isInteger(jobId) || jobId <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });

  const job = await prisma.ingestJob.findUnique({ where: { id: jobId }, include: { source: true } });
  if (!job) return NextResponse.json({ error: "항목을 찾을 수 없습니다." }, { status: 404 });
  // 검토 큐 목록과 동일 가시성(접근 가능한 scope면 미리보기 허용 — 읽기 전용).
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(job.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });

  let editSet: EditSet;
  try { editSet = JSON.parse(job.editSet || "{}") as EditSet; }
  catch { return NextResponse.json({ error: "편집셋 파싱 실패" }, { status: 500 }); }

  const edits: { op: string; path: string; isNew: boolean; diff: LineDiff }[] = [];
  for (const e of editSet.edits || []) {
    const epath = coercePath(job.teamScope, e.path);
    let current: string | null = null;
    try { current = await fs.readFile(wikiAbsPath(epath), "utf8"); } catch { /* 새 파일 */ }
    const isNew = current === null;
    // create+기존파일 = 전체 교체(diff). append·새 파일 = 전부 추가.
    const diff = e.op === "create" && !isNew ? diffLines(current as string, e.content) : allAdded(e.content);
    edits.push({ op: e.op, path: epath, isNew, diff });
  }

  return NextResponse.json({ jobId: job.id, scope: job.teamScope, summary: editSet.log_entry || "", edits });
}

export async function POST(req: Request, { params }: { params: Promise<{ jobId: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const jobId = Number((await params).jobId);
  if (!Number.isInteger(jobId) || jobId <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });
  const { action } = await req.json();

  const job = await prisma.ingestJob.findUnique({ where: { id: jobId }, include: { source: true } });
  if (!job || job.status !== "NEEDS_REVIEW") {
    return NextResponse.json({ error: "검토 대기 항목이 아닙니다." }, { status: 404 });
  }
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(job.teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });
  if (!(await canReview(user, job.teamScope))) {
    return NextResponse.json({ error: "검토 권한이 없습니다." }, { status: 403 });
  }

  if (action === "reject") {
    // 원자적 전이(동시 처리 방지)
    const r = await prisma.ingestJob.updateMany({
      where: { id: jobId, status: "NEEDS_REVIEW" },
      data: { status: "REJECTED" },
    });
    if (r.count !== 1) return NextResponse.json({ error: "이미 처리된 항목입니다." }, { status: 409 });
    return NextResponse.json({ ok: true, status: "REJECTED" });
  }

  if (action === "approve") {
    // ★ 원자적 클레임: NEEDS_REVIEW → APPLYING (동시 approve 이중적용·중복 커밋 방지).
    //   append op는 멱등이 아니라 두 번 적용되면 본문이 중복된다.
    const claim = await prisma.ingestJob.updateMany({
      where: { id: jobId, status: "NEEDS_REVIEW" },
      data: { status: "APPLYING" },
    });
    if (claim.count !== 1) return NextResponse.json({ error: "이미 처리 중이거나 완료된 항목입니다." }, { status: 409 });

    let editSet: EditSet;
    try {
      editSet = JSON.parse(job.editSet || "{}") as EditSet;
    } catch {
      await prisma.ingestJob.update({ where: { id: jobId }, data: { status: "NEEDS_REVIEW" } }).catch(() => {});
      return NextResponse.json({ error: "편집셋 파싱 실패" }, { status: 500 });
    }
    try {
      await assertWikiReady();
      const { commitSha, changed } = await withWikiWriteLock(async () => {
        // 갱신 전 각 대상 페이지의 기존 sha 수집(op:create가 옛 sha를 덮어써도 보강 — 자동적용과 동일).
        const preShaByPath = new Map<string, string[]>();
        for (const e of editSet.edits ?? []) {
          const rel = coercePath(job.teamScope, e.path);
          if (preShaByPath.has(rel)) continue;
          try { preShaByPath.set(rel, extractShas(await fs.readFile(wikiAbsPath(rel), "utf8"))); } catch { /* 새 페이지 */ }
        }
        const changed = await applyEditSet(job.teamScope, editSet);
        // ★원본 sha 출처 보장★ — 자동적용 경로(ingestText)와 동일하게, 적용된 지식 페이지마다 (기존 sha ∪ 원본 sha)를
        //   '## 출처'에 보강한다. 없으면 pages(sha 검색)가 빈값 → '위키 페이지를 찾지 못했습니다'(자료↔위키 이동 끊김).
        for (const rel of changed) {
          if (!/\/(entities|concepts|topics)\/[^/]+\.md$/.test(rel)) continue;
          const required = [...new Set([...(preShaByPath.get(rel) ?? []), job.source.sha256])];
          await ensureSourcesSection(wikiAbsPath(rel), required);
        }
        try { await regenerateIndex(job.teamScope); if (!changed.includes(`${job.teamScope}/index.md`)) changed.push(`${job.teamScope}/index.md`); } catch { /* skip */ } // 목차 표준화
        const commitSha = await commitAll(`review-approve(${job.teamScope}): ${job.source.title}`, {
          team: job.teamScope,
          gate: "HUMAN_REVIEW",
          sourceSha256: job.source.sha256,
          confidence: job.confidence ?? undefined,
          model: job.model ?? undefined,
        });
        return { commitSha, changed };
      });
      await prisma.ingestJob.update({ where: { id: jobId }, data: { status: "APPLIED", commitSha } });
      void syncWikiDocs(changed).catch(() => {}); // ★검색 색인 동기★(승인된 페이지가 키워드 검색에 뜨게)
      return NextResponse.json({ ok: true, status: "APPLIED", commitSha });
    } catch (err) {
      // 적용 실패 → 클레임 롤백(재시도 가능)
      await prisma.ingestJob.update({ where: { id: jobId }, data: { status: "NEEDS_REVIEW" } }).catch(() => {});
      return NextResponse.json({ error: String(err) }, { status: 500 });
    }
  }

  return NextResponse.json({ error: "action은 approve 또는 reject" }, { status: 400 });
}

