// ★JS 렌더링(번들/SPA) 페이지 감지★ — 콘텐츠를 JavaScript로 주입하는 HTML(웹빌드·SingleFile·시안 export 등)은
//   정적 추출 시 "This page requires JavaScript…/Unpacking…" 같은 ★셸 텍스트만★ 남는다. 이를 그대로 full로 통과시키면
//   LLM이 쓰레기를 분석해 무의미한 위키 페이지를 만든다 → ★none으로 폴백★해 원본만 보존(미분석)하고 사용자에게 신호.
//   판정: (a) JS 필요 안내 문구 + 짧은 추출, 또는 (b) HTML은 큰데(스크립트 다수) 추출 텍스트가 거의 없음.
function looksLikeJsShell(html: string, text: string): boolean {
  const jsRequired = /requires?\s+JavaScript|enable\s+JavaScript|JavaScript[를을]?\s*(?:켜|활성화|사용)|needs?\s+JavaScript|Unpacking[.…]/i.test(text);
  if (jsRequired && text.length < 600) return true;             // (a) 안내 문구 + 본문 거의 없음
  if (html.length > 30000 && text.replace(/\s+/g, "").length < 80) return true; // (b) 큰 HTML인데 알맹이 텍스트 거의 0
  return false;
}

async function extractHtml(html: string): Promise<ExtractResult> {
  const clean = html.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<style[\s\S]*?<\/style>/gi, "");
  const mod = await import("turndown");
  const Turndown = (mod as unknown as { default: new () => { turndown(s: string): string } }).default;
  const text = new Turndown().turndown(clean).trim();
  if (!text || looksLikeJsShell(html, text)) return { text: "", quality: "none", extractor: "turndown(js-shell)" };
  return { text, quality: "full", extractor: "turndown" };
}

