import { describe, it, expect } from "vitest";
import { looksLikeJsShell } from "../lib/extract";

// HTML 추출의 ★JS 렌더링(번들/SPA) 셸 감지★ 회귀 테스트(순수 로직).
// 버그: JS로 콘텐츠를 주입하는 큰 HTML이 "This page requires JavaScript…/Unpacking…" 셸만 추출됐는데
//   quality:full로 통과해 LLM이 쓰레기를 분석 → 검토대기·무의미 페이지. 이제 none으로 폴백(원본만 보존).
describe("looksLikeJsShell", () => {
  it("실제 버그 케이스 — 'requires JavaScript / Unpacking' 셸 감지", () => {
    const html = "<html><body><noscript>This page requires JavaScript to display.</noscript>" + "<script>".repeat(2000) + "</script></body></html>";
    const text = "Bundled Page\n\nThis page requires JavaScript to display.\n\nUnpacking...";
    expect(looksLikeJsShell(html, text)).toBe(true);
  });
  it("한국어 'JavaScript를 켜주세요' 안내 + 짧은 본문", () => {
    expect(looksLikeJsShell("<html>".repeat(100), "이 페이지를 보려면 JavaScript를 켜주세요.")).toBe(true);
  });
  it("큰 HTML인데 추출 텍스트가 거의 0 → 셸", () => {
    const big = "<div>" + "<span></span>".repeat(5000) + "</div>"; // 30KB+ 마크업, 알맹이 없음
    expect(looksLikeJsShell(big, "·")).toBe(true);
  });
  it("정상 콘텐츠 HTML은 셸 아님(추출 보존)", () => {
    const text = "헬름스맨은 사내 배포 자동화 도구다. ".repeat(40); // 충분한 본문
    expect(looksLikeJsShell("<html><body><p>" + text + "</p></body></html>", text)).toBe(false);
  });
  it("'JavaScript' 단어가 본문에 정상 등장해도 본문이 길면 셸 아님", () => {
    const text = "JavaScript는 웹 프로그래밍 언어입니다. ".repeat(40); // 600자 이상 실제 내용
    expect(looksLikeJsShell("<html>" + text + "</html>", text)).toBe(false);
  });
});

